INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1000, 'Dan''s Gold', 'Organic Dairy Compost', 'A premium COMPOST amendment derived from dairy manure, Dan''s Gold enriches soil by improving fertility and structure. Ideal for sustainable farming, it transforms gardens and agricultural lands into thriving ecosystems.', 'Amendment', 'DAIRY COMPOST', 'Dan''s Gold Organic Dairy Compost – Rich, Aged Compost for Garden Beds, Raised Beds & Soil Enrichment', 'Aging recreates natural biology and soil beneficial microbials', 'dairy compost, aged manure compost, organic compost soil, vegetable garden compost, flower bed soil amendment, compost for lawns, composted cow manure, raised bed soil booster, black gold soil, organic humus, garden compost organic, odorless compost, backyard compost mix, compost for trees, high quality compost', 'Organic Dairy Compost', 'Nursery Operators,Home Gardeners,Organic Farmers,Bad Conditions - Drought-resilient Agriculture,Floriculture,Fruit Growers,Vegetable Cultivators,Cannabis Cultivators,Garden Installation Organization', 'As an organic soil amendment, to mix with existing soil or potting soil', 'Rich in Organic Matter: Made from aged dairy manure composted for optimal nutrient availability|Feeds Soil Life: Packed with humus and microbes to build long-term soil health|Ideal for Veggies & Flowers: Great for garden beds, containers, lawns, and tree planting|Fully Composted, No Smell: Screened and aged for odor-free, safe application|Farmer-Approved Quality: Sourced from responsible dairy farms, free of synthetic chemicals', 'One of the two founders, Dan Nowell, started composting as a one-man operation in 2007 with a Tractor and a Windrower at Parker Dairy Farm. He learned to make an exceptional product the hard way and spent many days talking with both crop and dairy farmers alike to educate himself on what farmers need. Years later, Dan joined forces with Mike McMahon who significantly scaled the operation and incorporated scientific protocols to develop a consistent and reliable product. Dan''s Gold is made from composted dairy manure, a highly valued organic material that many farmers consider to be the best form of fertilizer. By utilizing waste from cows and adhering to the optimal composting process, Dan has managed to create a sustainable and effective product to improve soil health. There are numerous benefits of using composted manure versus raw manure, including a reduction in salt and odors.', 'Mix equal parts Dan''s Gold with existing soil or planting soil when planting. Top dress plants, windrows, and trees with 1"-2" of Dan''s Gold.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery,Bulk Pickup', 'DansGold9lbs (1).jpg', 'Compost Texture Look.jpg', ARRAY['dans-gold-batch-22.png', 'dans-gold-batch-24.png'], ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery', 'Bulk Pickup'], 0, 0, TRUE, 0, 'A premium COMPOST amendment derived from dairy manure, Dan''s Gold enriches soil by improving fertility and structure. Ideal for sustainable farming, it transforms gardens and agricultural lands into thriving ecosystems.', 'Compost Texture Look.jpg', FALSE, 0, 'active')
