INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1001, 'Mikey''s Worm Poop', 'Mikey''s Worm Poop', 'Mikey''s Worm Poop is an all-natural vermicompost offering a unique and organic solution to soil enhancement. This product has been developed after extensive research and trials, utilizing the very best of worm castings. Suitable for various industries, including agriculture, horticulture, and home gardening, Mikey''s Worm Poop can transform soil health, boost plant vitality, and contribute to sustainable farming practices.', 'Amendment', 'WORM CASTINGS', 'Mikey''s Worm Poop — Soil Seed & Water', 'Mikey''s Worm Poop is an all-natural vermicompost offering a unique and organic solution to soil enhancement. This product has been developed after extensive research and trials, utilizing the very best of worm castings. Suitable for various industries, including agriculture, horticulture, and home gardening, Mikey''s Worm Poop can transform soil health, boost plant vitality, and contribute to sustainable farming practices.', 'mikey''s, worm, poop', 'Worm Castings', 'Nursery Operators,Home Gardeners,Organic Farmers,Bad Conditions - Drought-resilient Agriculture,Floriculture,Fruit Growers,Vegetable Cultivators', 'As an organic soil amendment, to mix with existing soil or potting soil', 'It boosts soil health, promotes moisture retention, and supports vibrant plant growth. Certified organic, it''s the eco-friendly way to nourish your plants naturally.', 'When the founders of Soil, Seed, and Water, LLC heard countless farmers and gardeners raving about the wonders of worm castings as an organic fertilizer, they knew they had to explore this phenomenon further. They embarked on a journey of extensive research across the US and Canada, delving into the benefits and processes of vermicomposting. Seeking expert advice, the founders consulted with vermicomposting specialists and soon set up a vermiculture and vermicomposting operation in a one-and-a-half-acre commodity barn located within one of their compost dairies. Through their research, they discovered that their very own dairy compost was the perfect feedstock for worm nutrition. After several years of cultivating the herd and conducting meticulous research, worm population analysis, and trial and error, Soil, Seed & Water proudly introduced Mikey''s Worm Poop. This exceptional vermicompost product is the culmination of years dedication to understanding and perfecting the art of vermicomposting.', 'As an Organic Amendment - When planting in containers, dig holes and mix equal parts Mikey''s Worm Poop with existing soil or potting mix to backfill the plant. For Garden Beds and Mixing with Existing/Potting Soil - Gently till or fold 2" of Mikey''s Worm Poop into the top 4"-6" of the existing soil before planting or seeding. Top-dress Plants, Rows, and Trees (1/2" to 2") - Evenly spread 1"-2" of Mikey''s Worm Poop on the soil surface around the base of plants, along rows, or at the tree drip line.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery,Bulk Pickup', 'Mikeys Worm Poop9lbs.jpg', 'Worm castting product texture.png', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery', 'Bulk Pickup'], 0, 0, TRUE, 1, 'Mikey''s Worm Poop is an all-natural vermicompost offering a unique and organic solution to soil enhancement. This product has been developed after extensive research and trials, utilizing the very best of worm castings. Suitable for various industries, including agriculture, horticulture, and home gardening, Mikey''s Worm Poop can transform soil health, boost plant vitality, and contribute to sustainable farming practices.', 'Worm castting product texture.png', FALSE, 1, 'active')
