INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1002, 'Amazonian Dark Earth', 'Amazonian Dark Earth', 'Inspired by the fertile Terra Preta, Amazonian Dark Earth is a biochar-infused soil enhancer that promotes unparalleled soil health and sustainability, rich in essential minerals for a flourishing garden.', 'Amendment', 'BIOCHAR MINERAL', 'Amazonian Dark Earth — Soil Seed & Water', 'Inspired by the fertile Terra Preta, Amazonian Dark Earth is a biochar-infused soil enhancer that promotes unparalleled soil health and sustainability, rich in essential minerals for a flourishing garden.', 'amazonian, dark, earth', 'Biochar', 'Expert Gardeners', 'To enhance nutrient content in soil, can be mixed with existing soil', 'Inspired by the fertility of the Amazon, this biochar-enriched soil enhancer brings unparalleled sustainability and health to your garden. It''s a natural powerhouse for promoting soil vitality and plant vigor, all while being organic and odorless.', 'Archaeologists estimate that between 6 and 10 million people lived in the Amazon before the European conquest. They domesticated plants and animals, creating waste that they turned into compost over centuries, resulting in fertile soil known as Terra Preta. Today, we create biochar by anaerobically burning organic waste, providing a stable substrate for microbes. Soil Seed and Water''s Biochar is charged with our composted dairy manure, Dan''s Gold, containing essential minerals and nutrients. By developing Biochar and using Dan''s Gold Compost as a companion product, Soil Seed and Water brings Amazonian dark earth''s magic to the modern world, enhancing soil health and sustainability.', 'Mix 1 part Amazonian Dark Earth with 4 parts existing soil for new plantings or garden beds. For established plants, top-dress with 1/2" layer and gently work into the soil surface.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Amazonian1CF.jpg', 'Biochar Product Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 2, 'Inspired by the fertile Terra Preta, Amazonian Dark Earth is a biochar-infused soil enhancer that promotes unparalleled soil health and sustainability, rich in essential minerals for a flourishing garden.', 'Biochar Product Texture Look.jpg', FALSE, 2, 'active')
