INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1003, 'Tee Top Divot Repair Blend', 'Tee Top Divot Repair Blend', 'Perfect for golf courses, this blend repairs divots and maintains pristine playing surfaces, combining Zeolite and worm castings for optimal soil health and grass recovery.', 'Amendment', 'GOLF COURSE TEE TOP DIVOT REPAIR MIX', 'Tee Top Divot Repair Blend — Soil Seed & Water', 'Perfect for golf courses, this blend repairs divots and maintains pristine playing surfaces, combining Zeolite and worm castings for optimal soil health and grass recovery.', 'tee, top, divot, repair, blend', 'Zeolite,Worm Castings', 'Landscapers,Golf Courses', 'To repair divots on golf course tees, can be mixed with existing turf', 'Maintain pristine golf courses with our Divot Repair Blend, specially formulated for quick turf healing and regrowth. It''s natural, organic, and ensures a beautiful play area without the use of any harsh or odorous materials.', 'Soil Seed and Water, LLC, recognized a need for an effective solution to repair divots on premier golf courses and for damaged sport fields in the southwest. They developed Tee Top Divot Repair, a compost blend that includes water retention minerals, seamlessly integrating into the turf and promoting quick recovery. Tee Top Divot Repair is a concentrate, allowing golf course superintendents to mix it with readily available sand and seed for easy application. Designed exclusively for repairing divots on fairways and tee boxes, this product is also ideal for turf repair or patching on lawns, sports fields, and golf courses, catering to a variety of sports. With Tee Top Divot Repair, Soil Seed and Water has provided a versatile and efficient solution for maintaining pristine playing surfaces in a range of environments.', 'Fill divots on golf course tees with Tee Top Divot Repair, ensuring the material is level with the surrounding surface. Water lightly after application.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Tee Top1CF.jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 3, 'Perfect for golf courses, this blend repairs divots and maintains pristine playing surfaces, combining Zeolite and worm castings for optimal soil health and grass recovery.', 'Compost Texture Look.jpg', FALSE, 3, 'active')
