INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1004, 'Turf Daddy Blend', 'Turf Daddy Blend', 'Ideal for overseeding, aeration, and turf laying, Turf Daddy Blend improves soil quality and plant health with a mix of dairy compost, Zeolite, and worm castings, ensuring lush, resilient turf.', 'Amendment', 'OVERSEED TOPDRESS BLEND', 'Turf Daddy Blend — Soil Seed & Water', 'Ideal for overseeding, aeration, and turf laying, Turf Daddy Blend improves soil quality and plant health with a mix of dairy compost, Zeolite, and worm castings, ensuring lush, resilient turf.', 'turf, daddy, blend', 'Zeolite,Worm Castings,Organic Dairy Compost', 'Landscapers,Golf Courses,Nursery Operators', 'To overseed and aerate existing lawns, improves grass turf growth', 'Tailored for turf health, it encourages strong root development and improves soil structure. Enhances water retention and nutrient uptake, resulting in greener, denser lawns. Perfect for residential and commercial landscapes.', 'Turf Daddy Blend is blended in small batches by the Soil Seed & Water team using screened compost, minerals, and bioactive inputs for predictable results.', 'Broadcast Turf Daddy evenly over existing lawns at a rate of 1/4"-1/2" thick. Water thoroughly after application and continue to water as needed to maintain soil moisture.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Turf Daddy1CF.jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 4, 'Ideal for overseeding, aeration, and turf laying, Turf Daddy Blend improves soil quality and plant health with a mix of dairy compost, Zeolite, and worm castings, ensuring lush, resilient turf.', 'Compost Texture Look.jpg', FALSE, 4, 'active')
