INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1005, 'Artemis Root Boost Blend', 'Artemis Root Boost Blend', 'Specifically designed to support root health for trees and shrubs, Artemis Root Boost Blend enriches the soil with dairy compost and essential nutrients, promoting strong, healthy root systems in commercial and organic farming.', 'Amendment', 'TREE AND SHRUB PLANTING AMENDMENT', 'Artemis Root Boost Blend — Soil Seed & Water', 'Specifically designed to support root health for trees and shrubs, Artemis Root Boost Blend enriches the soil with dairy compost and essential nutrients, promoting strong, healthy root systems in commercial and organic farming.', 'artemis, root, boost, blend', 'Volcanic Tuff (Sulfur and Potassium Source),Organic Dairy Compost', 'Ornamental Plans,Landscapers,Trees,Fruit Growers', 'As a tree and shrub planting amendment, this blend is ideal for commercial and organic farmers, landscapers, and homeowner gardeners. It is designed to be mixed with existing soil.', 'Nurture the foundation of your garden with Artemis Root Boost. Focused on root health with organic and natural ingredients, it supports a thriving landscape without any odors, ensuring your plants have the perfect start.', 'Lucy, a passionate gardener and part-time landscaping consultant, was desperate to revive her struggling trees and shrubs. She tried many remedies, but nothing seemed to work. Then, she discovered Soil Seed and Water''s "Tree and Shrub Planting Amendment" and decided to give it a go. Excitedly, Lucy mixed the amendment into the backfill when planting new trees and shrubs, creating a nurturing environment for roots to thrive. She also top-dressed her existing trees and shrubs as part of her maintenance protocol. Soon, her garden transformed, as the trees and shrubs regained their lush, green appearance. Word spread about Lucy''s success, and Soil Seed and Water''s Tree and Shrub Planting Amendment became a popular choice among gardeners.', 'When planting trees and shrubs, mix equal parts Tree and Shrub Planting Amendment with existing soil to backfill the planting hole. Water thoroughly after planting.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Artemis10lbs (1).jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 5, 'Specifically designed to support root health for trees and shrubs, Artemis Root Boost Blend enriches the soil with dairy compost and essential nutrients, promoting strong, healthy root systems in commercial and organic farming.', 'Compost Texture Look.jpg', FALSE, 5, 'active')
