INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1006, 'Bacchus Blend', 'Bacchus Blend', 'A vineyard-specific enhancer, Bacchus Blend nourishes grapevines with dairy compost, worm castings, and vital minerals, ensuring top-quality wine production by promoting robust vine growth and fruit development.', 'Amendment', 'VINEYARD BLEND', 'Bacchus Blend — Soil Seed & Water', 'A vineyard-specific enhancer, Bacchus Blend nourishes grapevines with dairy compost, worm castings, and vital minerals, ensuring top-quality wine production by promoting robust vine growth and fruit development.', 'bacchus, blend', 'Organic Dairy Compost,Worm Castings,Zinc Sulfate,Iron Sulfate', 'Vineyards,Organic Farmers', 'To enrich vineyard soil, can be mixed with existing soil', 'Enhance your vineyard''s vitality with Bacchus Blend, designed for top-quality wine production. This organic, odorless formula enriches grapevines, ensuring growth and fruit quality that embody natural excellence.', 'Bacchus Blend is blended in small batches by the Soil Seed & Water team using screened compost, minerals, and bioactive inputs for predictable results.', 'Mix 1 part Bacchus with 4 parts existing soil for new vineyard plantings. For established vineyards, top-dress with 1/2" layer and gently work into the soil surface. Water thoroughly after application.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Bacchus1CF.jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 6, 'A vineyard-specific enhancer, Bacchus Blend nourishes grapevines with dairy compost, worm castings, and vital minerals, ensuring top-quality wine production by promoting robust vine growth and fruit development.', 'Compost Texture Look.jpg', FALSE, 6, 'active')
