INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1011, 'Zeolite', 'Zeolite', 'A natural mineral soil conditioner, Zeolite revitalizes garden soils by enhancing moisture retention and nutrient absorption, ensuring your garden remains hydrated and nutrient-rich.', 'Amendment', 'NATURAL MINERAL SOIL CONDITIONER', 'Zeolite — Soil Seed & Water', 'A natural mineral soil conditioner, Zeolite revitalizes garden soils by enhancing moisture retention and nutrient absorption, ensuring your garden remains hydrated and nutrient-rich.', 'zeolite', 'Zeolite combines premium composted organics with mineral-rich amendments and biochar to nourish soil life.', 'Home Gardeners,Turf Managers,Golf Courses,Horticulturists,Cannabis Cultivators', 'As a natural mineral soil conditioner, can be mixed with existing soil', 'Improves water retention and nutrient holding capacity of soils. Reduces leaching, ensuring plants receive a steady supply of essential nutrients. Also detoxifies soil by capturing heavy metals, promoting a healthier growing environment.', 'Soil Seed and Water, LLC, explored the potential of a unique crystalline mineral called Zeolite, composed of silicon, aluminum, and oxygen. This mineral possesses remarkable properties, with holes and channels that attract water and other tiny molecules. Adding Zeolite to soil enhances its moisture retention capacity, reducing surface runoff and protecting the soil from erosion. It''s particularly helpful for compacted, dense garden soil that struggles to absorb and retain water and nutrients. Zeolite''s benefits extend beyond water retention, making it a valuable soil amendment. With its multifaceted properties, Zeolite has become a crucial ingredient in Soil Seed and Water''s mission to improve soil health and sustainability. Another major attribute of Zeolite is that it doesn''t break down easily and stays in the soil for quite a long time.', 'Mix 1 part Zeolite with 4 parts existing soil for new plantings or garden beds. For established plants, top-dress with 1/2" layer and gently work into the soil surface. Water thoroughly after application.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote', 'Zeolite10lbs.jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote'], 0, 0, TRUE, 11, 'A natural mineral soil conditioner, Zeolite revitalizes garden soils by enhancing moisture retention and nutrient absorption, ensuring your garden remains hydrated and nutrient-rich.', 'Compost Texture Look.jpg', FALSE, 11, 'active')
