INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1012, 'SKMicrosource', 'SKMicrosource', 'Transforming gardens with improved water retention and pest protection, SKMicrosource is a blend of sulfur, gypsum, potassium, and micronutrients, ideal for revitalizing garden soils and promoting plant health.', 'Amendment', 'SULFUR-POTASSIUM NUTRITION BOOST', 'SKMicrosource — Soil Seed & Water', 'Transforming gardens with improved water retention and pest protection, SKMicrosource is a blend of sulfur, gypsum, potassium, and micronutrients, ideal for revitalizing garden soils and promoting plant health.', 'skmicrosource', 'Volcanic Tuff (Sulfur and Potassium Source)', 'Landscaping Professionals,Golf Courses,ASK MIKE,Organic Farmers,Ornamental Plans', 'Perfect for organic and conventional farming, home gardening, and landscaping. It can be mixed with composts, mulches, and animal manures approved for organic crops. Suitable for broadcast and foliar applications.', 'Provides a balanced mix of micro-nutrients essential for plant health. Enhances growth, fruiting, and flowering. Improves soil vitality, promoting beneficial microbial activity. Suitable for all types of plants and gardening methods.', 'A determined group of gardeners was on the hunt for the perfect soil amendment. Their search led them to SKMicrosource, a remarkable fusion of sulfur, gypsum, potassium, and a collection of essential micronutrients, all sourced from the Heart of Nature Mine in Tonopah, Nevada. This unique blend transformed their gardens, infusing the soil with essential nutrients, improving water retention, and offering exceptional pest protection. As the seasons turned, they incorporated SKMicrosource into their gardening routines. The difference was undeniable. Their plants flourished, basking in the wealth of nutrients and the improved soil health. Their secret weapon? SKMicrosource, the key to a vibrant, thriving garden, a product deeply rooted in the heart of nature, and a testament to the power of earth''s minerals.', 'For new plantings, mix 1/4 cup of SKMicrosource per 1 cubic foot of soil or planting mix. For established plants, apply 1/4 cup per 1 inch of trunk diameter, extending to the drip line. Water thoroughly after application.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote', 'SK Microsource10lbs.jpg', 'SKM Product Texture look.JPG', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote'], 0, 0, TRUE, 12, 'Transforming gardens with improved water retention and pest protection, SKMicrosource is a blend of sulfur, gypsum, potassium, and micronutrients, ideal for revitalizing garden soils and promoting plant health.', 'SKM Product Texture look.JPG', FALSE, 12, 'active')
