INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1013, 'Desert Defender', 'Desert Defender', 'Combatting drought conditions, this unique blend of Zeolite, dairy compost, and essential minerals supports rich, green fields, ensuring your soil remains fertile and moisture-rich even in dry conditions.', 'Amendment', 'DROUGHT RESILIENCE SOIL AMENDMENT', 'Desert Defender — Soil Seed & Water', 'Combatting drought conditions, this unique blend of Zeolite, dairy compost, and essential minerals supports rich, green fields, ensuring your soil remains fertile and moisture-rich even in dry conditions.', 'desert, defender', 'Zeolite,Volcanic Tuff (Sulfur and Potassium Source),Organic Dairy Compost', 'ASK MIKE,Bad Conditions - Drought-resilient Agriculture', 'Serves as a rescue soil amendment in drought situations, making it an ideal choice for the agriculture industry, landscapers, and environment conservationists.', 'Crafted for optimum water retention, its organic blend combats the harshest conditions, ensuring your soil stays hydrated and healthy. Harness the power of nature with this naturally resilient formula designed for thriving growth, even in times of drought.', 'Dan''s Drought Mix, a product of the "Make the Mesa Green Initiative," is a real-life embodiment of Dan''s dedication to sustainability, the co-founder of Soil Seed and Water. Dan saw potential in the sandy, dry soils on the Mesa in Yuma, Arizona, where growing plants seemed nearly impossible. His deep understanding of soil and the desire to turn infertile lands into rich green fields led to this unique blend. Made of Zeolite, SKMicrosource, and our unique Dan''s Gold, this mix nourishes the soil, fights against drought, and supports bountiful harvests where once only barren sands lay. In essence, Dan''s Drought Mix is more than just a soil amendment—it symbolizes resilience, innovation, and the power of combining science with nature to overcome challenges and build a greener, sustainable world.', 'Mix 1 part Dan''s Drought Mix with 4 parts existing soil for new plantings or garden beds. For established plants, top-dress with 1/2" layer and gently work into the soil surface. Water thoroughly after application.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Dans Drought10lbs.jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 13, 'Combatting drought conditions, this unique blend of Zeolite, dairy compost, and essential minerals supports rich, green fields, ensuring your soil remains fertile and moisture-rich even in dry conditions.', 'Compost Texture Look.jpg', FALSE, 13, 'active')
