INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1014, 'Silky Silt Saver', 'Silky Silt Saver', 'Silky Silt Saver is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Amendment', 'SILT SOIL DROUGHT BLEND FOR ENHANCED MOISTURE RETENTION', 'Silky Silt Saver — Soil Seed & Water', 'Silky Silt Saver is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'silky, silt, saver', 'Organic Dairy Compost,Zeolite,Worm Castings,Volcanic Tuff (Sulfur and Potassium Source),Humic and Fulvic Acids,Biochar', 'Landscaping Professionals', 'Ideal for farming, landscaping, and home gardening. Blend with compost, mulch, or use directly as a soil amendment to improve silt soil performance. Perfect for top-dressing or integrating into soil for drought resilience and plant health. Composition: Micronized Biochar, Bentonite Clay, Organic Humic Acids, Trace Minerals.', 'Silky Silt Saver improves soil structure, balances moisture, and feeds biology for consistent performance at scale.', 'At Soil Seed and Water, we recognize the challenges of cultivating in silt soils, especially under drought conditions. Silky Silt Saver is our answer—a blend meticulously crafted to improve moisture retention, boost nutrient availability, and support healthy soil structure. Inspired by nature''s resilience, this blend harmonizes premium ingredients like Micronized Biochar, Bentonite Clay, and Organic Humic Acids. These components empower silt soils to stay hydrated longer, ensuring your plants thrive even in challenging conditions. Perfect for farmers, landscapers, and gardeners, Silky Silt Saver embodies the balance between nature and innovation, preparing your soil for sustainability and success.', 'For general use, spread Silky Silt Saver evenly at a rate of 1 cup per square foot. Incorporate into the top 1/2 inch of soil or mix with compost for best results. Water thoroughly after application to activate its moisture-holding properties.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Compost Texture Look.jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 14, 'Silky Silt Saver is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Compost Texture Look.jpg', FALSE, 14, 'active')
