INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (1015, 'Clay Cure', 'Clay Cure', 'Clay Cure is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Amendment', 'CLAY SOIL DROUGHT BLEND FOR IMPROVED SOIL BALANCE', 'Clay Cure — Soil Seed & Water', 'Clay Cure is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'clay, cure', 'Organic Dairy Compost,Worm Castings,Zeolite,Volcanic Tuff (Sulfur and Potassium Source),Humic Acid,Biochar', 'Landscaping Professionals', 'Perfect for farming, landscaping, and home gardening. Clay Cure can be used in vegetable gardens, flower beds, lawns, and potted plants. Mix with compost or apply directly to improve soil texture, reduce compaction, and increase water retention. Composition: Bentonite Clay, Micronized Biochar, Organic Humic Acids, Trace Minerals.', 'Clay Cure improves soil structure, balances moisture, and feeds biology for consistent performance at scale.', 'Clay soils may be rich, but their challenges can be daunting. That''s why we created Clay Cure—a transformative solution tailored to unlock the full potential of heavy silt and clay soils. Designed to optimize water retention and aeration, this blend empowers your soil to support robust plant growth even in arid conditions. Combining natural components like Bentonite Clay, Micronized Biochar, and Organic Humic Acids, Clay Cure delivers enhanced moisture balance and nutrient availability. It''s more than an amendment—it''s a partner in transforming your soil into a thriving, resilient foundation for growth.', 'Apply Clay Cure as a top-dressing or mix into the soil at a rate of 1 cup per square foot. For larger areas, broadcast at a rate of 5 pounds per 1,000 square feet. Water thoroughly after application to activate its full potential.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote', 'Compost Texture Look.jpg', 'Compost Texture Look.jpg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote'], 0, 0, TRUE, 15, 'Clay Cure is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Compost Texture Look.jpg', FALSE, 15, 'active')
