INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (2000, 'Ready Go Garden', 'Ready Go Garden', 'Ready Go Garden, an organic potting soil within a grow bag, ensures successful harvests with its nutrient-rich composition and excellent drainage properties. Designed for the ease of container gardening, this grow bag is your go-to solution for lush, productive gardens without the need for traditional garden beds. Perfect for patios, balconies, or any space-constrained environment, it empowers gardeners to cultivate a variety of plants in a convenient and efficient manner.', 'Potting Soil', 'PREMIUM POTTING SOIL', 'Ready Go Garden — Soil Seed & Water', 'Ready Go Garden, an organic potting soil within a grow bag, ensures successful harvests with its nutrient-rich composition and excellent drainage properties. Designed for the ease of container gardening, this grow bag is your go-to solution for lush, productive gardens without the need for traditional garden beds. Perfect for patios, balconies, or any space-constrained environment, it empowers gardeners to cultivate a variety of plants in a convenient and efficient manner.', 'ready, go, garden', 'Clean Wood Fiber,Worm Castings,Biochar,Kelp Meal,Azomite,Bioblend (Trackaderma, root shield),Mycorrhizal Granular Endo Package,Cyanobacteria,Volcanic Tuff (Sulfur and Potassium Source),Organic Dairy Compost,Manganese,Iron,Magnesium,Boron,Zinc,Calcium,Molybdenum,Cobalt,Copper,Zeolite', 'Floriculture,Fruit Growers,Nursery Operators,Vegetable Cultivators,Home Gardeners', 'Ideal for preparing garden beds, to mix with existing soil or potting soil', 'Perfect pH Balance: Ensures optimal growth conditions. Enhanced Drainage: Prevents overwatering and root rot. Rich in Organic Matter: For sustained plant nutrition. Suitable for Various Plants: From herbs to ornamental plants. Easy-to-Use: Ready to use right out of the bag.', 'The inspiration for the Ready Go Garden Grow Bag was drawn from Soil Seed and Water''s successful product, the "SuperBooster." The founders envisioned a versatile growing bag that would cater to a variety of crops with high rotation rates, ensuring the perfect balance of nutrients for optimal growth. Collaborating with agronomists, biologists, seed producers, and farmers they developed the versatile "All-Purpose Ready Go Garden Godfathers Blend." With the knowledge gained from developing the Superbooster, the team meticulously crafted the Ready Go Garden Grow Bag. This innovative product is ideal for leafy greens such as arugula, kale, and mustard greens, as well as root crops like potatoes, carrots, beets, onions, and radishes. Additionally, it''s perfect for flowers with root diameters no larger than a pencil and crops with a rapid maturation rate (less than 90 days). The Ready Go Garden Grow Bag is a testament to Soil Seed and Water''s dedication to providing tailored solutions for diverse gardening needs, all while building upon the success of their previous products.', 'Use Ready Go Garden as a complete planting medium for container plants or raised beds. No need to mix with existing soil. Water thoroughly after planting.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'RGG9lbs.jpg', 'Default Potting Soil Texture.jpeg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 16, 'Ready Go Garden, an organic potting soil within a grow bag, ensures successful harvests with its nutrient-rich composition and excellent drainage properties. Designed for the ease of container gardening, this grow bag is your go-to solution for lush, productive gardens without the need for traditional garden beds. Perfect for patios, balconies, or any space-constrained environment, it empowers gardeners to cultivate a variety of plants in a convenient and efficient manner.', 'Default Potting Soil Texture.jpeg', FALSE, 16, 'active')
