INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (2001, 'CannaBag', 'CannaBag', 'Specially formulated for cannabis cultivation, CannaBag is not just a potting soil but also a grow bag, creating an optimal growth environment with its rich, sustainable mix. It caters specifically to the unique needs of cannabis plants, supporting unparalleled growth and potency. Ideal for growers looking for an all-in-one solution, the CannaBag offers convenience and high performance in indoor, greenhouse, or limited outdoor spaces, ensuring your cannabis plants thrive from seedling to harvest.', 'Potting Soil', 'CANNABIS POTTING SOIL', 'CannaBag — Soil Seed & Water', 'Specially formulated for cannabis cultivation, CannaBag is not just a potting soil but also a grow bag, creating an optimal growth environment with its rich, sustainable mix. It caters specifically to the unique needs of cannabis plants, supporting unparalleled growth and potency. Ideal for growers looking for an all-in-one solution, the CannaBag offers convenience and high performance in indoor, greenhouse, or limited outdoor spaces, ensuring your cannabis plants thrive from seedling to harvest.', 'cannabag', 'Clean Wood Fiber,Superbooster,Biochar', 'Home Gardeners,Cannabis Cultivators', 'As an organic soil amendment, specifically designed for cannabis cultivation', 'Enhances root aeration and drainage, promoting vigorous plant growth. Its breathable fabric leads to healthier root structures and prevents over-watering issues, ensuring optimal plant health and yield. Ideal for both indoor and outdoor gardening.', 'Legend has it that 400-year-old pipes with traces of cannabis were discovered in Shakespeare''s garden in Stratford-upon-Avon. Inspired by this historical connection, the team at Soil Seed and Water, LLC, recognized the growing demand for a specialized cannabis grow bag. They had already found success with their Ready Go Garden grow bag but knew that cannabis plants required a unique blend of nutrients for optimal growth. After many trials, they stumbled upon a previously "failed" attempt that turned out to be perfect for Cannabis plants. This "hot mix" provided the nutrient-rich environment required for cannabis to flourish. Thus, Cannabag was born, a carefully crafted blend of organic composted ingredients designed to unleash the full potential of cannabis plants and spark that Shakespearean creativity in its users.', 'Use CannaBag as a complete planting medium for cannabis plants. No need to mix with existing soil. Water thoroughly after planting and maintain a consistent watering schedule.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'Cannabag10lbs.jpg', 'Default Potting Soil Texture.jpeg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 17, 'Specially formulated for cannabis cultivation, CannaBag is not just a potting soil but also a grow bag, creating an optimal growth environment with its rich, sustainable mix. It caters specifically to the unique needs of cannabis plants, supporting unparalleled growth and potency. Ideal for growers looking for an all-in-one solution, the CannaBag offers convenience and high performance in indoor, greenhouse, or limited outdoor spaces, ensuring your cannabis plants thrive from seedling to harvest.', 'Default Potting Soil Texture.jpeg', FALSE, 17, 'active')
