INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (2002, 'Succulent Success', 'Succulent Success', 'Succulent Success is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Potting Soil', 'SUCCULENT INTERIOR POTTING MIX', 'Succulent Success — Soil Seed & Water', 'Succulent Success is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'succulent, success', 'Pumice ( 1/16 Cinder Sand),Perlite,Coco Coir,Organic Dairy Compost,Zeolite,Volcanic Tuff (Sulfur and Potassium Source),Clear Amino Acid', 'Landscapers', 'Perfect for indoor and outdoor succulents, cacti, and other low-water plants. Use as a standalone potting mix or blend with your existing soil for added drainage and structure. Ideal for planters, terrariums, and garden beds. Composition: Pumice, Coconut Coir, Organic Compost, Micronized Minerals, Essential Micronutrients.', 'Succulent Success improves soil structure, balances moisture, and feeds biology for consistent performance at scale.', 'Not all soils are created equal—succulents require something truly special. Succulent Success is a potting mix designed with precision to meet the unique needs of these hardy, water-storing plants. Crafted for optimal drainage and balanced nutrients, this blend ensures your succulents flourish in pots, gardens, and arrangements. Combining elements like Pumice, Coconut Coir, and Organic Compost with essential micronutrients, Succulent Success provides the perfect foundation for strong roots and vibrant growth. Whether you''re caring for a single echeveria or curating a sprawling desert garden, this mix is tailored for success.', 'For potted plants, fill the container with Succulent Success, leaving room for planting. Gently place the succulent and cover the roots. For outdoor use, mix with existing soil to improve drainage. Water lightly after planting to settle the mix.', 'Pallet of 9 lb bags,Pallet of 1CF bags', 'Default Potting Soil Texture.jpeg', 'Default Potting Soil Texture.jpeg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags'], 0, 0, TRUE, 18, 'Succulent Success is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Default Potting Soil Texture.jpeg', FALSE, 18, 'active')
