INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (2003, 'Tropic Treasure', 'Tropic Treasure', 'Tropic Treasure is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Potting Soil', 'TROPICAL PLANT INTERIOR POTTING MIX', 'Tropic Treasure — Soil Seed & Water', 'Tropic Treasure is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'tropic, treasure', 'Coco Coir,Organic Dairy Compost,Perlite,Vermiculite,Zeolite,Clear Amino Acid', 'Landscape contractors, commercial growers, nurseries, and retail partners.', 'Perfect for tropical plants, including monstera, philodendrons, palms, and orchids. Use Tropic Treasure as a standalone potting mix for containers or blend with garden soil to improve moisture retention and structure. Great for indoor and outdoor settings. Composition: Coconut Coir, Orchid Bark, Organic Compost, Volcanic Rock Dust, Essential Micronutrients.', 'Tropic Treasure improves soil structure, balances moisture, and feeds biology for consistent performance at scale.', 'Soil Seed and Water brings the tropics to your home with Tropic Treasure, a premium potting mix designed to replicate the lush, nutrient-rich environments tropical plants thrive in. This blend balances moisture retention and aeration to support the needs of vibrant foliage and flowering tropicals like monstera, philodendrons, and orchids. Tropic Treasure combines Coconut Coir, Orchid Bark, and Organic Compost, enhanced with volcanic rock dust and essential micronutrients. Each ingredient plays a role in creating the perfect environment for tropical plants, ensuring deep root development and lush, vigorous growth. From balconies to greenhouses, this mix helps your tropicals flourish like never before.', 'For potted plants, fill the container with Tropic Treasure, leaving space for planting. Place the tropical plant, ensuring the roots are well-covered, and water thoroughly. For garden beds, mix with existing soil at a ratio of 1:1 for enhanced performance.', 'Pallet of 9 lb bags,Pallet of 1CF bags', 'Default Potting Soil Texture.jpeg', 'Default Potting Soil Texture.jpeg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags'], 0, 0, TRUE, 19, 'Tropic Treasure is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Default Potting Soil Texture.jpeg', FALSE, 19, 'active')
