INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (2004, 'Flower Flourish', 'Flower Flourish', 'Flower Flourish is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Potting Soil', 'FLOWERING PLANT INTERIOR POTTING MIX', 'Flower Flourish — Soil Seed & Water', 'Flower Flourish is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'flower, flourish', 'Coco Coir,Organic Dairy Compost,Perlite,Vermiculite,Zeolite,Clear Amino Acid', 'Landscapers', 'Ideal for flowering plants like petunias, geraniums, marigolds, and daisies. Use Flower Flourish as a standalone potting mix for containers, hanging baskets, or blend it with garden soil to improve nutrient content and structure. Suitable for both indoor and outdoor applications. Composition: Coconut Coir, Organic Compost, Volcanic Rock Dust, Micronized Minerals, Essential Micronutrients.', 'Flower Flourish improves soil structure, balances moisture, and feeds biology for consistent performance at scale.', 'Soil Seed and Water is proud to present Flower Flourish, a specialized potting mix tailored to support the beauty and vitality of flowering plants. Designed to provide balanced nutrition, excellent drainage, and moisture retention, this blend creates the perfect foundation for vibrant blooms and healthy foliage. Combining Coconut Coir, Organic Compost, and Micronized Minerals with a touch of Volcanic Rock Dust, Flower Flourish delivers essential nutrients for continuous flowering. Whether used for garden beds, pots, or hanging baskets, this mix brings your flowering plants to life, ensuring they reach their full blooming potential.', 'Fill the container with Flower Flourish, leaving enough space for planting. Place your flowering plant and cover the roots thoroughly. Water generously after planting to help the soil settle. For garden beds, mix with existing soil at a 1:1 ratio to enrich and condition the planting area.', 'Pallet of 9 lb bags,Pallet of 1CF bags', 'Default Potting Soil Texture.jpeg', 'Default Potting Soil Texture.jpeg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags'], 0, 0, TRUE, 20, 'Flower Flourish is part of Soil Seed & Water''s professional wholesale collection, crafted for demanding growers and landscapers.', 'Default Potting Soil Texture.jpeg', FALSE, 20, 'active')
