INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (3000, 'Nature''s Blanket Premium Mulch', 'Nature''s Blanket Premium Mulch', 'Premium mulch enhanced with dairy compost and worm castings, providing superior moisture retention, weed suppression, and soil enhancement. Available in multiple sizes for various landscaping applications.', 'Mulch', 'ALL-IN-ONE DARK MULCH ENHANCED WITH WORM CASTING AND DAIRY COMPOST', 'Nature''s Blanket Premium Mulch — Soil Seed & Water', 'Premium mulch enhanced with dairy compost and worm castings, providing superior moisture retention, weed suppression, and soil enhancement. Available in multiple sizes for various landscaping applications.', 'nature''s, blanket, premium, mulch', 'Clean Wood Fiber, Organic Dairy Compost, Worm Castings', 'Landscapers', 'Ideal for garden beds, landscaping projects, and erosion control. Use Nature''s Blanket as a mulch to retain moisture and reduce weed growth, or mix with soil to enhance fertility and structure. Perfect for covering bare soil and protecting it from environmental stressors. Available in multiple sizes (.5-1" and 1-2") for various applications including commercial parks, residential projects, and garden beds.', 'Enhances moisture retention, Suppresses weeds, Improves soil structure, Decorative finish, Professional-grade quality, Long-lasting results', 'Soil Seed and Water introduces Nature''s Blanket Premium Mulch, a sustainable solution crafted to nurture and protect your soil. This premium blend combines the insulating properties of premium wood fibers with the nutrient-rich benefits of dairy compost and worm castings, creating a versatile soil amendment and protective cover. Nature''s Blanket helps regulate moisture, reduce erosion, and enrich soil fertility, ensuring a thriving foundation for your plants. Designed for both commercial landscapers and residential gardeners, Nature''s Blanket provides an eco-friendly way to maintain soil health while promoting sustainability. Whether used as a mulch, erosion control, or soil amendment, this blend embodies a harmony of natural elements working together to create optimal growing conditions.', 'For mulching, spread Nature''s Blanket evenly over the soil surface at a depth of 2–3 inches. For soil amendment, mix into the top 2–4 inches of soil at a ratio of 1:1 with existing soil. Water thoroughly after application to activate its nutrient potential.', 'Pallet of 1CF bags,Bulk Delivery', 'Dark Mulk Applied in outside of office showcase.jpeg', 'Dark Mulk Applied in outside of office showcase.jpeg', ARRAY['Dark Mulk Applied in outside of office showcase.jpeg', 'Raw Golden Looking Mulch Commercial Application look.jpeg', 'Dark Mulck Truckload Delivery.jpeg'], ARRAY['Pallet of 1CF bags', 'Bulk Delivery'], 0, 0, TRUE, 21, 'Premium mulch enhanced with dairy compost and worm castings, providing superior moisture retention, weed suppression, and soil enhancement. Available in multiple sizes for various landscaping applications.', 'Dark Mulk Applied in outside of office showcase.jpeg', FALSE, 21, 'active')
