INSERT INTO products (id, name, display_title, description, category, product_type, marketing_title, marketing_note, seo_keywords, ingredients, target_audience, recommended_uses, features, story, usage, size_options, image_url, texture_photo_url, additional_images, available_size_options, price, stock_quantity, is_catalog_enabled, catalog_display_order, pay_and_pickup_description, pay_and_pickup_hero_image, is_pay_and_pickup_enabled, pay_and_pickup_display_order, product_status)
VALUES (4000, 'SuperBooster', 'SuperBooster', 'SuperBooster is an organic concentrated soil amendment that enriches soil with macro and micronutrients, diverse microbial biology, and structural elements. Crafted to serve as a supplemental plant food, SuperBooster ensures optimal water absorption, drainage, and mineral content. Its application ranges from home gardens to commercial farming and specialty crops, making it a preferred choice for sustainable growth.', 'Concentrated Amendment', 'CONCENTRATED AMENDMENT FOR FRUITS AND VEGETABLES', 'SuperBooster — Soil Seed & Water', 'SuperBooster is an organic concentrated soil amendment that enriches soil with macro and micronutrients, diverse microbial biology, and structural elements. Crafted to serve as a supplemental plant food, SuperBooster ensures optimal water absorption, drainage, and mineral content. Its application ranges from home gardens to commercial farming and specialty crops, making it a preferred choice for sustainable growth.', 'superbooster', 'Clean Wood Fiber,Worm Castings,Biochar,Kelp Meal,Zeolite,Azomite,Bioblend (Trackaderma, root shield),Mycorrhizal Granular Endo Package,Cyanobacteria,Volcanic Tuff (Sulfur and Potassium Source),Organic Dairy Compost,Manganese,Iron,Magnesium,Boron,Zinc,Calcium,Molybdenum,Cobalt,Copper', 'Fruit Growers,Vegetable Cultivators,Home Gardeners', 'Add as a concentrated soil amendment. Do not use as potting soil, rather as an amendment of existing soil', 'It''s perfect for giving your plants the upper hand in growth and health. Dive into organic excellence and watch your garden thrive.', 'SuperBooster is blended in small batches by the Soil Seed & Water team using screened compost, minerals, and bioactive inputs for predictable results.', 'Mix 1 part SuperBooster with 4 parts existing soil for new plantings or garden beds. For established plants, top-dress with 1/2" layer and gently work into the soil surface.', 'Pallet of 9 lb bags,Pallet of 1CF bags,2.2 CY Tote,Bulk Delivery', 'SuperBooster (1).jpg', 'Concentrated Organic Amendment Fertilizer Product look.jpeg', NULL, ARRAY['Pallet of 9 lb bags', 'Pallet of 1CF bags', '2.2 CY Tote', 'Bulk Delivery'], 0, 0, TRUE, 22, 'SuperBooster is an organic concentrated soil amendment that enriches soil with macro and micronutrients, diverse microbial biology, and structural elements. Crafted to serve as a supplemental plant food, SuperBooster ensures optimal water absorption, drainage, and mineral content. Its application ranges from home gardens to commercial farming and specialty crops, making it a preferred choice for sustainable growth.', 'Concentrated Organic Amendment Fertilizer Product look.jpeg', FALSE, 22, 'active')
